from pathlib import Path
p=Path('smartflow-runtime.js')
s=p.read_text(encoding='utf-8')
old="function modal(title,body){let m=$('sfRuntimeModal');if(!m){m=document.createElement('div');m.id='sfRuntimeModal';m.className='sf-modal';document.body.appendChild(m)}m.innerHTML=`<div class=\"sf-box\"><div class=\"row\"><h2 style=\"margin:0\">${title}</h2><button class=\"btn soft\" onclick=\"sfCloseRuntimeModal()\">×</button></div><div style=\"margin-top:12px\">${body}</div></div>`;m.classList.add('open')}"
new="function modal(title,body){let m=$('sfRuntimeModal');if(!m){m=document.createElement('div');m.id='sfRuntimeModal';m.className='sf-modal';const st=document.createElement('style');st.textContent='.sf-modal{position:fixed;inset:0;background:#001827aa;z-index:999;display:none;align-items:flex-end;justify-content:center;padding:10px}.sf-modal.open{display:flex}.sf-box{width:min(760px,100%);max-height:94vh;overflow:auto;background:#fff;border-radius:22px;padding:18px;box-shadow:0 30px 80px #0005}.sf-form{display:grid;gap:9px}.sf-form label{font-size:11px;font-weight:800;color:var(--muted)}.sf-form input,.sf-form select{padding:11px;border:1px solid var(--line);border-radius:10px}';document.head.appendChild(st);document.body.appendChild(m)}m.innerHTML=`<div class=\"sf-box\"><div class=\"row\"><h2 style=\"margin:0\">${title}</h2><button class=\"btn soft\" type=\"button\" onclick=\"sfCloseRuntimeModal()\">×</button></div><div style=\"margin-top:12px\">${body}</div></div>`;m.classList.add('open')}"
if old not in s: raise SystemExit('runtime modal target not found')
p.write_text(s.replace(old,new,1),encoding='utf-8')
